//!
//! Storing the exact minimum and maximum values in the column statistics can blow up the
//! footer size when a column contains very large string or binary values. To keep the
//! statistics small we truncate the bounds to at most a configurable number of bytes.
//!
//! The truncation length is controlled by the `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN`
//! environment variable. When unset it defaults to [`DEFAULT_TRUNCATE_LEN`] bytes. Setting it
//! to `0` disables truncation entirely, so the statistics reflect the exact values.

use crate::parquet::schema::types::{PrimitiveLogicalType, PrimitiveType};

const TRUNCATE_LEN_ENV: &str = "POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN";

/// The default number of bytes statistics bounds are truncated to.
const DEFAULT_TRUNCATE_LEN: usize = 64;

/// Returns the configured statistics truncation length.
///
/// - `None` means truncation is disabled (the environment variable is set to `0`).
/// - `Some(n)` means bounds should be truncated to at most `n` bytes.
fn truncate_len() -> Option<usize> {
    let len = match std::env::var(TRUNCATE_LEN_ENV) {
        Ok(v) => v.trim().parse::<usize>().unwrap_or(DEFAULT_TRUNCATE_LEN),
        Err(_) => DEFAULT_TRUNCATE_LEN,
    };
    (len != 0).then_some(len)
}

/// Whether the column holds UTF-8 encoded strings (as opposed to opaque binary).
fn is_utf8(primitive_type: &PrimitiveType) -> bool {
    matches!(
        primitive_type.logical_type,
        Some(PrimitiveLogicalType::String)
    )
}

/// Truncate a minimum-statistics bound.
///
/// For UTF-8 columns the value is truncated to the longest valid UTF-8 prefix that fits within
/// the byte limit. For binary columns it is truncated at the raw byte level.
pub(crate) fn truncate_min_value(primitive_type: &PrimitiveType, value: &[u8]) -> Vec<u8> {
    let Some(limit) = truncate_len() else {
        return value.to_vec();
    };
    if value.len() <= limit {
        return value.to_vec();
    }

    if is_utf8(primitive_type) {
        match std::str::from_utf8(value) {
            Ok(s) => truncate_utf8(s, limit).unwrap_or_else(|| value.to_vec()),
            // Should not happen for a string column, but fall back to a byte-level truncation.
            Err(_) => value[..limit].to_vec(),
        }
    } else {
        value[..limit].to_vec()
    }
}

/// Truncate a maximum-statistics bound.
///
/// The truncated value is incremented so that it remains a valid *upper* bound for every value
/// in the column. For UTF-8 columns the last character is incremented while preserving its
/// encoded byte length; for binary columns the last non-`0xFF` byte is incremented.
pub(crate) fn truncate_max_value(primitive_type: &PrimitiveType, value: &[u8]) -> Vec<u8> {
    let Some(limit) = truncate_len() else {
        return value.to_vec();
    };
    if value.len() <= limit {
        return value.to_vec();
    }

    if is_utf8(primitive_type) {
        match std::str::from_utf8(value) {
            Ok(s) => truncate_and_increment_utf8(s, limit).unwrap_or_else(|| value.to_vec()),
            Err(_) => truncate_and_increment_binary(value, limit).unwrap_or_else(|| value.to_vec()),
        }
    } else {
        truncate_and_increment_binary(value, limit).unwrap_or_else(|| value.to_vec())
    }
}

/// Truncate a valid UTF-8 string to the longest valid UTF-8 prefix that fits within `length`
/// bytes. Returns `None` if not even the first character fits.
fn truncate_utf8(data: &str, length: usize) -> Option<Vec<u8>> {
    let mut boundary = 0;
    for (idx, c) in data.char_indices() {
        let next = idx + c.len_utf8();
        if next > length {
            break;
        }
        boundary = next;
    }
    (boundary != 0).then(|| data.as_bytes()[..boundary].to_vec())
}

/// Increment the last character of a valid UTF-8 byte string, preserving the encoded byte length
/// of the incremented character. Works right-to-left so that a character at its maximum value for
/// its width is skipped in favour of an earlier one. Returns `None` if no character can be
/// incremented.
fn increment_utf8(data: &[u8]) -> Option<Vec<u8>> {
    let s = std::str::from_utf8(data).ok()?;
    for (idx, c) in s.char_indices().rev() {
        let len = c.len_utf8();
        if let Some(next) = char::from_u32(c as u32 + 1) {
            // Do not allow the increment to grow the character's encoded byte length.
            if next.len_utf8() == len {
                let mut result = data[..idx + len].to_vec();
                next.encode_utf8(&mut result[idx..]);
                return Some(result);
            }
        }
    }
    None
}

/// Produce a truncated, incremented upper bound for a UTF-8 string.
fn truncate_and_increment_utf8(data: &str, length: usize) -> Option<Vec<u8>> {
    let truncated = truncate_utf8(data, length)?;
    increment_utf8(&truncated)
}

/// Produce a truncated, incremented upper bound for a binary value.
///
/// The last non-`0xFF` byte within the limit is incremented and any trailing bytes are dropped.
/// If every byte within the limit is `0xFF`, the search extends beyond the limit to the first
/// non-`0xFF` byte so that a valid upper bound can still be produced. Returns `None` if the whole
/// value consists of `0xFF` bytes (in which case no finite upper bound exists).
fn truncate_and_increment_binary(data: &[u8], length: usize) -> Option<Vec<u8>> {
    if let Some(i) = data[..length].iter().rposition(|&b| b != 0xFF) {
        let mut result = data[..=i].to_vec();
        result[i] += 1;
        return Some(result);
    }

    // All bytes within the limit are `0xFF`; search beyond the limit for the first byte that can
    // be incremented.
    let rel = data[length..].iter().position(|&b| b != 0xFF)?;
    let j = length + rel;
    let mut result = data[..=j].to_vec();
    result[j] += 1;
    Some(result)
}
