#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn utf8_min_ascii() {
        let data = "A".repeat(100);
        assert_eq!(truncate_utf8(&data, 64).unwrap(), b"A".repeat(64));
    }

    #[test]
    fn utf8_min_respects_char_boundary() {
        // 63 'A' followed by a 2-byte character.
        let data = format!("{}\u{00e9}", "A".repeat(63));
        assert_eq!(data.len(), 65);
        // The 2-byte char is excluded to avoid splitting it.
        assert_eq!(truncate_utf8(&data, 64).unwrap(), b"A".repeat(63));
    }

    #[test]
    fn utf8_max_ascii() {
        let data = "A".repeat(100);
        let expected = format!("{}B", "A".repeat(63));
        assert_eq!(
            truncate_and_increment_utf8(&data, 64).unwrap(),
            expected.as_bytes()
        );
    }

    #[test]
    fn utf8_max_multibyte() {
        // Many 2-byte chars; 32 of them fill the 64-byte budget exactly.
        let data = "\u{00e9}".repeat(40);
        let expected = format!("{}\u{00ea}", "\u{00e9}".repeat(31));
        assert_eq!(
            truncate_and_increment_utf8(&data, 64).unwrap(),
            expected.as_bytes()
        );
    }

    #[test]
    fn binary_max_all_ff_within_limit_searches_beyond() {
        let mut data = vec![0xFFu8; 8];
        data.push(0x00);
        data.extend(std::iter::repeat_n(0xFFu8, 6));
        assert_eq!(data.len(), 15);

        let mut expected = vec![0xFFu8; 8];
